      backup_text =
        "# NIGHT GARDEN NUTRIENT TRACKER #\n\
         # Soil management for sustainable moonlight farming #\n\n\
         # Soil nutrients are measured 0-100 #\n\
         # N = Nitrogen (leafy growth), P = Phosphorus (roots), K = Potassium \
         (health) #\n\
         type Soil = (\n\
        \  n = Int,\n\
        \  p = Int,\n\
        \  k = Int\n\
         ) in\n\n\
         # The mystical crops of the night garden #\n\
         type Crop =\n\
        \  + Duskwheat    # Nitrogen fixer - restores N when harvested #\n\
        \  + Moonmelon    # Heavy feeder - depletes N significantly #\n\
        \  + Starfruit    # Balanced - moderate use of all nutrients #\n\
        \  + Nightshade   # Cover crop - restores N when turned under #\n\
         in\n\n\
         # A garden plot has soil state, optionally a growing crop, and a \
         season #\n\
         type Model = (\n\
        \  soil = Soil,\n\
        \  crop = +None +Some(Crop),\n\
        \  season = Int\n\
         ) in\n\n\
         type Action =\n\
        \  + Plant(Crop)     # Plant a new crop (fails if plot occupied) #\n\
        \  + Harvest         # Harvest current crop, apply nutrient effects #\n\
        \  + Compost         # Add organic matter, boosts all nutrients #\n\
        \  + SeasonChange    # Time passes, nutrients settle #\n\
         in\n\n\
         let clamp(x: Int): Int =\n\
        \  if x < 0 then 0\n\
        \  else if x > 100 then 100\n\
        \  else x\n\
         in\n\n\
         let balancedSoil: Soil = (n = 60, p = 60, k = 60) in\n\n\
         let init: Model = (\n\
        \  soil = balancedSoil,\n\
        \  crop = None,\n\
        \  season = 1\n\
         ) in\n\n\
         # Establishing a crop costs a little of what it needs most #\n\
         let plantingCost(s: Soil, crop: Crop): Soil =\n\
        \  case crop\n\
        \  | Duskwheat => (n = s.n, p = clamp(s.p - 5), k = clamp(s.k - 5))\n\
        \  | Moonmelon => (n = clamp(s.n - 5), p = clamp(s.p - 5), k = \
         clamp(s.k - 5))\n\
        \  | Starfruit => (n = clamp(s.n - 5), p = clamp(s.p - 5), k = \
         clamp(s.k - 5))\n\
        \  | Nightshade => (n = s.n, p = clamp(s.p - 3), k = clamp(s.k - 3))\n\
        \  end\n\
         in\n\n\
         # Harvesting is the main nutrient exchange: crops deplete or restore #\n\
         let harvestEffect(s: Soil, crop: Crop): Soil =\n\
        \  case crop\n\
        \  | Duskwheat =>\n\
        \      # Nitrogen fixer: restores N, uses some P and K #\n\
        \      (n = clamp(s.n + 15), p = clamp(s.p - 10), k = clamp(s.k - 10))\n\
        \  | Moonmelon =>\n\
        \      # Heavy N feeder: depletes nitrogen significantly #\n\
        \      (n = clamp(s.n - 30), p = clamp(s.p - 10), k = clamp(s.k - 15))\n\
        \  | Starfruit =>\n\
        \      # Balanced consumer: moderate depletion across all #\n\
        \      (n = clamp(s.n - 15), p = clamp(s.p - 15), k = clamp(s.k - 15))\n\
        \  | Nightshade =>\n\
        \      # Cover crop turned under: major N restoration #\n\
        \      (n = clamp(s.n + 20), p = clamp(s.p - 5), k = clamp(s.k - 5))\n\
        \  end\n\
         in\n\n\
         let applyCompost(s: Soil): Soil =\n\
        \  (n = clamp(s.n + 10), p = clamp(s.p + 10), k = clamp(s.k + 10))\n\
         in\n\n\
         let seasonSettle(s: Soil): Soil =\n\
        \  (n = clamp(s.n - 3), p = clamp(s.p - 2), k = clamp(s.k - 2))\n\
         in\n\n\
         let update(action: Action, plot: Model): (Model, Cmd) =\n\
        \  case action\n\
        \  | Plant(crop) =>\n\
        \      # Only plant if the plot is empty #\n\
        \      case plot.crop\n\
        \      | Some(_) => (plot, CmdNone)\n\
        \      | None =>\n\
        \          (\n\
        \            (\n\
        \              soil = plantingCost(plot.soil, crop),\n\
        \              crop = Some(crop),\n\
        \              season = plot.season\n\
        \            ),\n\
        \            CmdNone\n\
        \          )\n\
        \      end\n\
        \  | Harvest =>\n\
        \      case plot.crop\n\
        \      | None => (plot, CmdNone)\n\
        \      | Some(crop) =>\n\
        \          (\n\
        \            (\n\
        \              soil = harvestEffect(plot.soil, crop),\n\
        \              crop = None,\n\
        \              season = plot.season\n\
        \            ),\n\
        \            CmdNone\n\
        \          )\n\
        \      end\n\
        \  | Compost =>\n\
        \      (\n\
        \        (soil = applyCompost(plot.soil), crop = plot.crop, season = \
         plot.season),\n\
        \        CmdNone\n\
        \      )\n\
        \  | SeasonChange =>\n\
        \      (\n\
        \        (soil = seasonSettle(plot.soil), crop = plot.crop, season = \
         plot.season + 1),\n\
        \        CmdNone\n\
        \      )\n\
        \  end\n\
         in\n\n\
         # ===== VIEW HELPERS ===== #\n\n\
         let seasonName(s: Int): String =\n\
        \  let phase = int_mod(s - 1, 4) in\n\
        \  if phase == 0 then \"Spring\"\n\
        \  else if phase == 1 then \"Summer\"\n\
        \  else if phase == 2 then \"Autumn\"\n\
        \  else \"Winter\"\n\
         in\n\n\
         let seasonEmoji(s: Int): String =\n\
        \  let phase = int_mod(s - 1, 4) in\n\
        \  if phase == 0 then \"\240\159\140\177\"\n\
        \  else if phase == 1 then \"\240\159\140\153\"\n\
        \  else if phase == 2 then \"\240\159\141\130\"\n\
        \  else \"\226\157\132\239\184\143\"\n\
         in\n\n\
         let cropName(c: Crop): String =\n\
        \  case c\n\
        \  | Duskwheat => \"Duskwheat\"\n\
        \  | Moonmelon => \"Moonmelon\"\n\
        \  | Starfruit => \"Starfruit\"\n\
        \  | Nightshade => \"Nightshade\"\n\
        \  end\n\
         in\n\n\
         let cropEmoji(c: Crop): String =\n\
        \  case c\n\
        \  | Duskwheat => \"\240\159\140\190\"\n\
        \  | Moonmelon => \"\240\159\141\136\"\n\
        \  | Starfruit => \"\240\159\140\159\"\n\
        \  | Nightshade => \"\240\159\141\135\"\n\
        \  end\n\
         in\n\n\
         # ===== VIEW ===== #\n\n\
         let view(model: Model): HTML =\n\n\
        \  # Shared style values #\n\
        \  let darkBg = (\"background\", \"#0d1117\") in\n\
        \  let cardBg = (\"background\", \"#161b22\") in\n\
        \  let textColor = (\"color\", \"#c9d1d9\") in\n\
        \  let fontFamily = (\"font-family\", \"monospace, sans-serif\") in\n\
        \  let borderStyle = (\"border\", \"1px solid #30363d\") in\n\n\
        \  # Nutrient bar: label, value 0-100, color #\n\
        \  let nutrientBar(label: String, value: Int, color: String): HTML =\n\
        \    let widthPct = string_of_int(value) ++ \"%\" in\n\
        \    Div(\n\
        \      [Style([(\"margin-bottom\", \"12px\")])],\n\
        \      [\n\
        \        Div(\n\
        \          [Style([(\"display\", \"flex\"), (\"justify-content\", \
         \"space-between\"), (\"margin-bottom\", \"4px\")])],\n\
        \          [\n\
        \            Span([Style([(\"color\", \"#8b949e\"), (\"font-size\", \
         \"13px\")])], [Text(label)]),\n\
        \            Span([Style([(\"color\", color), (\"font-size\", \
         \"13px\"), (\"font-weight\", \"bold\")])],\n\
        \                 [Text(string_of_int(value) ++ \"/100\")])\n\
        \          ]\n\
        \        ),\n\
        \        Div(\n\
        \          [Style([(\"width\", \"100%\"), (\"height\", \"18px\"), \
         (\"background\", \"#21262d\"),\n\
        \                  (\"border-radius\", \"9px\"), (\"overflow\", \
         \"hidden\"), (\"border\", \"1px solid #30363d\")])],\n\
        \          [\n\
        \            Div(\n\
        \              [Style([(\"width\", widthPct), (\"height\", \"18px\"), \
         (\"background\", color),\n\
        \                      (\"border-radius\", \"9px\"), (\"transition\", \
         \"width 0.3s\")])],\n\
        \              []\n\
        \            )\n\
        \          ]\n\
        \        )\n\
        \      ]\n\
        \    )\n\
        \  in\n\n\
        \  let actionButton(label: String, action: Action, bg: String): HTML =\n\
        \    Button(\n\
        \      [\n\
        \        OnClick(action),\n\
        \        Style([\n\
        \          (\"padding\", \"10px 18px\"), (\"margin\", \"5px\"),\n\
        \          (\"background\", bg), (\"color\", \"#e0e0e0\"),\n\
        \          (\"border\", \"1px solid #30363d\"), (\"border-radius\", \
         \"6px\"),\n\
        \          (\"cursor\", \"pointer\"), (\"font-size\", \"14px\"),\n\
        \          (\"font-weight\", \"bold\"), fontFamily\n\
        \        ])\n\
        \      ],\n\
        \      [Text(label)]\n\
        \    )\n\
        \  in\n\n\
        \  let cropDisplay =\n\
        \    case model.crop\n\
        \    | None =>\n\
        \        Div(\n\
        \          [Style([(\"text-align\", \"center\"), (\"padding\", \
         \"16px\"), cardBg,\n\
        \                  (\"border-radius\", \"8px\"), borderStyle, \
         (\"margin-bottom\", \"16px\")])],\n\
        \          [\n\
        \            Div([Style([(\"font-size\", \"36px\"), \
         (\"margin-bottom\", \"4px\")])], \
         [Text(\"\240\159\140\171\239\184\143\")]),\n\
        \            Div([Style([(\"color\", \"#8b949e\"), (\"font-size\", \
         \"14px\")])], [Text(\"Fallow - No crop planted\")])\n\
        \          ]\n\
        \        )\n\
        \    | Some(c) =>\n\
        \        Div(\n\
        \          [Style([(\"text-align\", \"center\"), (\"padding\", \
         \"16px\"), cardBg,\n\
        \                  (\"border-radius\", \"8px\"), borderStyle, \
         (\"margin-bottom\", \"16px\")])],\n\
        \          [\n\
        \            Div([Style([(\"font-size\", \"36px\"), \
         (\"margin-bottom\", \"4px\")])], [Text(cropEmoji(c))]),\n\
        \            Div([Style([(\"color\", \"#c9d1d9\"), (\"font-size\", \
         \"16px\"), (\"font-weight\", \"bold\")])], [Text(cropName(c))]),\n\
        \            Div([Style([(\"color\", \"#8b949e\"), (\"font-size\", \
         \"12px\"), (\"margin-top\", \"4px\")])], [Text(\"Currently \
         growing\")])\n\
        \          ]\n\
        \        )\n\
        \    end\n\
        \  in\n\n\
        \  let plantButtons =\n\
        \    case model.crop\n\
        \    | Some(_) =>\n\
        \        [\n\
        \          Div(\n\
        \            [Style([(\"text-align\", \"center\"), (\"color\", \
         \"#484f58\"), (\"font-size\", \"12px\"), (\"padding\", \"8px\")])],\n\
        \            [Text(\"Clear the field first (harvest) to plant\")]\n\
        \          )\n\
        \        ]\n\
        \    | None =>\n\
        \        [\n\
        \          actionButton(\"\240\159\140\190 Duskwheat\", \
         Plant(Duskwheat), \"#3a3a1a\"),\n\
        \          actionButton(\"\240\159\141\136 Moonmelon\", \
         Plant(Moonmelon), \"#1a3a2a\"),\n\
        \          actionButton(\"\240\159\140\159 Starfruit\", \
         Plant(Starfruit), \"#3a3320\"),\n\
        \          actionButton(\"\240\159\141\135 Nightshade\", \
         Plant(Nightshade), \"#2a1a3a\")\n\
        \        ]\n\
        \    end\n\
        \  in\n\n\
        \  Div(\n\
        \    [Style([\n\
        \      darkBg, textColor, fontFamily,\n\
        \      (\"max-width\", \"480px\"), (\"margin\", \"20px auto\"),\n\
        \      (\"padding\", \"24px\"), (\"border-radius\", \"12px\"),\n\
        \      (\"border\", \"2px solid #30363d\"),\n\
        \      (\"box-shadow\", \"0 0 40px rgba(80, 200, 120, 0.15)\")\n\
        \    ])],\n\
        \    [\n\
        \      H1(\n\
        \        [Style([(\"text-align\", \"center\"), (\"color\", \
         \"#3fb950\"), (\"margin-bottom\", \"4px\"), (\"font-size\", \
         \"22px\")])],\n\
        \        [Text(\"\240\159\140\153 Moonlit Soil Lab \240\159\140\153\")]\n\
        \      ),\n\
        \      P(\n\
        \        [Style([(\"text-align\", \"center\"), (\"color\", \
         \"#8b949e\"), (\"margin-top\", \"0\"), (\"margin-bottom\", \"16px\"), \
         (\"font-size\", \"12px\")])],\n\
        \        [Text(\"Nutrient management for the night garden\")]\n\
        \      ),\n\n\
        \      # Season indicator #\n\
        \      Div(\n\
        \        [Style([(\"text-align\", \"center\"), (\"padding\", \
         \"12px\"), cardBg,\n\
        \                (\"border-radius\", \"8px\"), borderStyle, \
         (\"margin-bottom\", \"16px\")])],\n\
        \        [\n\
        \          Span([Style([(\"font-size\", \"28px\")])], \
         [Text(seasonEmoji(model.season))]),\n\
        \          Span(\n\
        \            [Style([(\"font-size\", \"18px\"), (\"color\", \
         \"#58a6ff\"), (\"margin-left\", \"12px\"), (\"font-weight\", \
         \"bold\")])],\n\
        \            [Text(seasonName(model.season))]\n\
        \          ),\n\
        \          Span(\n\
        \            [Style([(\"font-size\", \"13px\"), (\"color\", \
         \"#8b949e\"), (\"margin-left\", \"8px\")])],\n\
        \            [Text(\"(Season \" ++ string_of_int(model.season) ++ \
         \")\")]\n\
        \          )\n\
        \        ]\n\
        \      ),\n\n\
        \      # Soil nutrients #\n\
        \      H3(\n\
        \        [Style([(\"color\", \"#3fb950\"), (\"margin-bottom\", \
         \"8px\"), (\"font-size\", \"14px\")])],\n\
        \        [Text(\"\240\159\167\170 Soil Nutrients\")]\n\
        \      ),\n\
        \      Div(\n\
        \        [Style([(\"padding\", \"14px\"), cardBg, (\"border-radius\", \
         \"8px\"),\n\
        \                borderStyle, (\"margin-bottom\", \"16px\")])],\n\
        \        [\n\
        \          nutrientBar(\"N  Nitrogen\", model.soil.n, \"#3fb950\"),\n\
        \          nutrientBar(\"P  Phosphorus\", model.soil.p, \"#bc8cff\"),\n\
        \          nutrientBar(\"K  Potassium\", model.soil.k, \"#f0883e\")\n\
        \        ]\n\
        \      ),\n\n\
        \      # Current crop #\n\
        \      H3(\n\
        \        [Style([(\"color\", \"#3fb950\"), (\"margin-bottom\", \
         \"8px\"), (\"font-size\", \"14px\")])],\n\
        \        [Text(\"\240\159\140\190 Current Crop\")]\n\
        \      ),\n\
        \      cropDisplay,\n\n\
        \      # Plant buttons #\n\
        \      H3(\n\
        \        [Style([(\"color\", \"#3fb950\"), (\"margin-bottom\", \
         \"8px\"), (\"font-size\", \"14px\")])],\n\
        \        [Text(\"\240\159\140\177 Plant\")]\n\
        \      ),\n\
        \      Div(\n\
        \        [Style([(\"display\", \"flex\"), (\"flex-wrap\", \"wrap\"), \
         (\"justify-content\", \"center\"), (\"margin-bottom\", \"16px\")])],\n\
        \        plantButtons\n\
        \      ),\n\n\
        \      # Actions #\n\
        \      H3(\n\
        \        [Style([(\"color\", \"#3fb950\"), (\"margin-bottom\", \
         \"8px\"), (\"font-size\", \"14px\")])],\n\
        \        [Text(\"\226\154\151\239\184\143 Actions\")]\n\
        \      ),\n\
        \      Div(\n\
        \        [Style([(\"display\", \"flex\"), (\"flex-wrap\", \"wrap\"), \
         (\"justify-content\", \"center\"), (\"margin-bottom\", \"16px\")])],\n\
        \        [\n\
        \          actionButton(\"\240\159\140\191 Harvest\", Harvest, \
         \"#238636\"),\n\
        \          actionButton(\"\240\159\167\145\226\128\141\240\159\140\190 \
         Compost\", Compost, \"#6e4000\"),\n\
        \          actionButton(\"\240\159\148\132 Season Change\", \
         SeasonChange, \"#1f6feb\")\n\
        \        ]\n\
        \      ),\n\n\
        \      Div(\n\
        \        [Style([(\"text-align\", \"center\"), (\"color\", \
         \"#484f58\"), (\"font-size\", \"11px\"),\n\
        \                (\"margin-top\", \"12px\"), (\"padding-top\", \
         \"12px\"), (\"border-top\", \"1px solid #21262d\")])],\n\
        \        [Text(\"\240\159\140\153 Night Garden | N:\" ++ \
         string_of_int(model.soil.n)\n\
        \              ++ \" P:\" ++ string_of_int(model.soil.p)\n\
        \              ++ \" K:\" ++ string_of_int(model.soil.k))]\n\
        \      )\n\
        \    ]\n\
        \  )\n\
         in\n\n\
         let subs(_model: Model): Sub = SubNone in\n\n\
         # ===== TESTS ===== #\n\n\
         let step(acc: Model, a: Action): Model = let (m, _cmd) = update(a, \
         acc) in m in\n\
         let run(plot: Model, actions: [Action]): Model = fold_left(actions, \
         step, plot) in\n\n\
         hint \"planting sets the current crop\"\n\
         test\n\
        \  let (p, _cmd) = update(Plant(Moonmelon), init) in\n\
        \  p.crop == Some(Moonmelon)\n\
         end;\n\n\
         hint \"cannot plant when crop already growing\"\n\
         test\n\
        \  let p = run(init, [Plant(Moonmelon), Plant(Starfruit)]) in\n\
        \  p.crop == Some(Moonmelon)\n\
         end;\n\n\
         hint \"planting has small nutrient cost\"\n\
         test\n\
        \  let (p, _cmd) = update(Plant(Starfruit), init) in\n\
        \  p.soil.n < init.soil.n\n\
         end;\n\n\
         hint \"harvesting clears the crop\"\n\
         test\n\
        \  let p = run(init, [Plant(Moonmelon), Harvest]) in\n\
        \  p.crop == None\n\
         end;\n\n\
         hint \"harvesting nothing changes nothing\"\n\
         test\n\
        \  let (p, _cmd) = update(Harvest, init) in\n\
        \  p == init\n\
         end;\n\n\
         hint \"moonmelon depletes nitrogen heavily\"\n\
         test\n\
        \  let p = run(init, [Plant(Moonmelon), Harvest]) in\n\
        \  p.soil.n < init.soil.n - 20\n\
         end;\n\n\
         hint \"duskwheat restores nitrogen\"\n\
         test\n\
        \  let depleted: Model = (\n\
        \    soil = (n = 30, p = 50, k = 50),\n\
        \    crop = None,\n\
        \    season = 1\n\
        \  ) in\n\
        \  let p = run(depleted, [Plant(Duskwheat), Harvest]) in\n\
        \  p.soil.n > depleted.soil.n\n\
         end;\n\n\
         hint \"nightshade restores nitrogen significantly\"\n\
         test\n\
        \  let depleted: Model = (\n\
        \    soil = (n = 30, p = 60, k = 60),\n\
        \    crop = None,\n\
        \    season = 1\n\
        \  ) in\n\
        \  let p = run(depleted, [Plant(Nightshade), Harvest]) in\n\
        \  p.soil.n >= 45\n\
         end;\n\n\
         hint \"starfruit depletes all nutrients moderately\"\n\
         test\n\
        \  let p = run(init, [Plant(Starfruit), Harvest]) in\n\
        \  p.soil.n < init.soil.n &&\n\
        \  p.soil.p < init.soil.p &&\n\
        \  p.soil.k < init.soil.k\n\
         end;\n\n\
         hint \"compost boosts all nutrients\"\n\
         test\n\
        \  let (p, _cmd) = update(Compost, init) in\n\
        \  p.soil.n > init.soil.n &&\n\
        \  p.soil.p > init.soil.p &&\n\
        \  p.soil.k > init.soil.k\n\
         end;\n\n\
         hint \"compost respects maximum (100)\"\n\
         test\n\
        \  let rich: Model = (soil = (n = 95, p = 95, k = 95), crop = None, \
         season = 1) in\n\
        \  let (p, _cmd) = update(Compost, rich) in\n\
        \  p.soil.n == 100 && p.soil.p == 100 && p.soil.k == 100\n\
         end;\n\n\
         hint \"season advances counter\"\n\
         test\n\
        \  let (p, _cmd) = update(SeasonChange, init) in\n\
        \  p.season == 2\n\
         end;\n\n\
         hint \"season change causes minor nutrient loss\"\n\
         test\n\
        \  let (p, _cmd) = update(SeasonChange, init) in\n\
        \  p.soil.n < init.soil.n\n\
         end;\n\n\
         hint \"moonmelon then nightshade rotation restores nitrogen\"\n\
         test\n\
        \  let afterMoonmelon = run(init, [Plant(Moonmelon), Harvest]) in\n\
        \  let afterNightshade = run(afterMoonmelon, [Plant(Nightshade), \
         Harvest]) in\n\
        \  afterNightshade.soil.n > afterMoonmelon.soil.n &&\n\
        \  afterNightshade.soil.n >= 40\n\
         end;\n\n\
         hint \"nutrients cannot go below 0\"\n\
         test\n\
        \  let poor: Model = (soil = (n = 10, p = 10, k = 10), crop = None, \
         season = 1) in\n\
        \  let p = run(poor, [Plant(Moonmelon), Harvest]) in\n\
        \  p.soil.n >= 0 && p.soil.p >= 0 && p.soil.k >= 0\n\
         end;\n\n\
         hint \"nutrients cannot exceed 100\"\n\
         test\n\
        \  let rich: Model = (soil = (n = 90, p = 90, k = 90), crop = None, \
         season = 1) in\n\
        \  let p = run(rich, [Compost, Compost, Compost]) in\n\
        \  p.soil.n <= 100 && p.soil.p <= 100 && p.soil.k <= 100\n\
         end;\n\n\
         (init, update, view, subs)\n";
      refractors = "()";
    } )
